-- Normalize demo gig addresses to street-only values.
-- Rationale: gigs.address should only contain street address text; city/state are
-- captured separately in location/state fields.

UPDATE public.gigs
SET address = CASE id
  -- Banana Stand gigs
  WHEN '00000000-0000-4000-8301-000000000001'::uuid THEN '110 Newport Center Dr'
  WHEN '00000000-0000-4000-8301-000000000002'::uuid THEN '4333 MacArthur Blvd'
  WHEN '00000000-0000-4000-8301-000000000003'::uuid THEN '124 Agate Ave'
  WHEN '00000000-0000-4000-8301-000000000004'::uuid THEN '24601 Sudden Valley Rd'
  WHEN '00000000-0000-4000-8301-000000000005'::uuid THEN '110 Newport Center Dr'
  WHEN '00000000-0000-4000-8301-000000000006'::uuid THEN '4333 MacArthur Blvd'
  WHEN '00000000-0000-4000-8301-000000000007'::uuid THEN '124 Agate Ave'

  -- Modal Nodes gigs
  WHEN '00000000-0000-4000-8302-000000000001'::uuid THEN '7 Cantina Row'
  WHEN '00000000-0000-4000-8302-000000000002'::uuid THEN 'Hangar Bay 94'
  WHEN '00000000-0000-4000-8302-000000000003'::uuid THEN 'Great Pit of Carkoon Rd'
  WHEN '00000000-0000-4000-8302-000000000004'::uuid THEN '7 Cantina Row'
  WHEN '00000000-0000-4000-8302-000000000005'::uuid THEN 'Level 22 Bespin Tower'
  WHEN '00000000-0000-4000-8302-000000000006'::uuid THEN '7 Cantina Row'
  WHEN '00000000-0000-4000-8302-000000000007'::uuid THEN '7 Cantina Row'
  ELSE address
END
WHERE id IN (
  '00000000-0000-4000-8301-000000000001'::uuid,
  '00000000-0000-4000-8301-000000000002'::uuid,
  '00000000-0000-4000-8301-000000000003'::uuid,
  '00000000-0000-4000-8301-000000000004'::uuid,
  '00000000-0000-4000-8301-000000000005'::uuid,
  '00000000-0000-4000-8301-000000000006'::uuid,
  '00000000-0000-4000-8301-000000000007'::uuid,
  '00000000-0000-4000-8302-000000000001'::uuid,
  '00000000-0000-4000-8302-000000000002'::uuid,
  '00000000-0000-4000-8302-000000000003'::uuid,
  '00000000-0000-4000-8302-000000000004'::uuid,
  '00000000-0000-4000-8302-000000000005'::uuid,
  '00000000-0000-4000-8302-000000000006'::uuid,
  '00000000-0000-4000-8302-000000000007'::uuid
);
